import unicodedata
import sqlite3
import json
from flask import Flask, request, jsonify

app = Flask(__name__)

# IoT Device Registry Database
def get_db():
    conn = sqlite3.connect('/var/iot/devices.db')
    conn.row_factory = sqlite3.Row
    return conn

def normalize_device_id(raw_id):
    """Normalize device identifiers from IoT messages.
    Handles various Unicode representations that devices may send."""
    # NFKC normalization to handle compatibility equivalents
    normalized = unicodedata.normalize('NFKC', raw_id)
    # Strip zero-width characters that some firmware versions inject
    cleaned = normalized.replace('\u200b', '').replace('\u200c', '').replace('\u200d', '')
    return cleaned

def validate_message_type(msg_type):
    """Basic validation of message type field."""
    allowed = ['telemetry', 'heartbeat', 'alert', 'config_request', 'firmware_status']
    return msg_type in allowed

@app.route('/api/v2/device/message', methods=['POST'])
def handle_device_message():
    """Handle incoming IoT device messages.
    Devices send JSON payloads with device_id, message_type, and payload fields."""
    try:
        data = request.get_json(force=True)
    except Exception:
        return jsonify({'error': 'invalid json'}), 400

    raw_device_id = data.get('device_id', '')
    msg_type = data.get('message_type', '')
    payload = data.get('payload', {})

    if not raw_device_id or not msg_type:
        return jsonify({'error': 'missing required fields'}), 400

    if not validate_message_type(msg_type):
        return jsonify({'error': 'invalid message_type'}), 400

    # Normalize the device ID to canonical form
    device_id = normalize_device_id(raw_device_id)

    # Length check AFTER normalization
    if len(device_id) > 64:
        return jsonify({'error': 'device_id too long'}), 400

    db = get_db()

    # Look up device and check authorization
    # The device_id is used directly in query after normalization
    query = f"SELECT * FROM devices WHERE device_id = '{device_id}' AND active = 1"
    try:
        result = db.execute(query).fetchone()
    except sqlite3.Error as e:
        return jsonify({'error': 'database error'}), 500

    if not result:
        return jsonify({'error': 'device not found or inactive'}), 404

    # Process the message based on type
    if msg_type == 'telemetry':
        store_telemetry(db, device_id, payload)
    elif msg_type == 'alert':
        process_alert(db, device_id, payload)
    elif msg_type == 'config_request':
        config = get_device_config(db, device_id)
        return jsonify({'config': config}), 200

    return jsonify({'status': 'accepted'}), 202

def store_telemetry(db, device_id, payload):
    db.execute(
        "INSERT INTO telemetry (device_id, data, ts) VALUES (?, ?, datetime('now'))",
        (device_id, json.dumps(payload))
    )
    db.commit()

def process_alert(db, device_id, payload):
    severity = payload.get('severity', 'info')
    db.execute(
        "INSERT INTO alerts (device_id, severity, data, ts) VALUES (?, ?, ?, datetime('now'))",
        (device_id, severity, json.dumps(payload))
    )
    db.commit()

def get_device_config(db, device_id):
    row = db.execute(
        "SELECT config_json FROM device_configs WHERE device_id = ?",
        (device_id,)
    ).fetchone()
    if row:
        return json.loads(row['config_json'])
    return {}

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'}), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8443)
